/*
 * Remote Servo Control (ESP32)
 *
 * Control a servo motor from your phone!
 * Use the D35 slider on the remote to
 * set the servo angle (0-180 degrees).
 *
 * How to use:
 * 1. Run this sketch
 * 2. Click the Remote button (phone icon)
 * 3. Open the URL on your phone
 * 4. Slide D35 to control servo angle
 */

#include <Servo.h>

Servo myServo;
int servoPin = 13;

void setup() {
  Serial.begin(115200);
  myServo.attach(servoPin);
  myServo.write(90);
  Serial.println("ESP32 Servo ready!");
  Serial.println("Slide D35 to control angle.");
}

void loop() {
  int val = analogRead(35);
  int angle = map(val, 0, 4095, 0, 180);
  myServo.write(angle);
  delay(50);
}
